require_once __DIR__.'/includes/auth.php';requireLogin();$pdo=db();$uid=userId();$pageTitle='Export & Backup';$activePage='export.php';$allowed=['transactions','income','expense','debts','receivables','savings'];$dataset=$_GET['dataset']??'transactions';$format=$_GET['format']??'';
if($format==='csv'||$format==='json'){$queries=['transactions'=>'SELECT transaction_date,type,category,description,amount FROM transactions WHERE user_id=? ORDER BY transaction_date DESC','income'=>'SELECT transaction_date,category,description,amount FROM transactions WHERE user_id=? AND type="income" ORDER BY transaction_date DESC','expense'=>'SELECT transaction_date,category,description,amount FROM transactions WHERE user_id=? AND type="expense" ORDER BY transaction_date DESC','debts'=>'SELECT name,total_amount,paid_amount,due_date,status,description FROM debts WHERE user_id=? ORDER BY due_date','receivables'=>'SELECT name,total_amount,paid_amount,due_date,status,description FROM receivables WHERE user_id=? ORDER BY due_date','savings'=>'SELECT name,target_amount,current_amount,deadline,description FROM savings WHERE user_id=? ORDER BY deadline'];$dataset=in_array($dataset,$allowed,true)?$dataset:'transactions';$st=$pdo->prepare($queries[$dataset]);$st->execute([$uid]);$data=$st->fetchAll();$filename='keuangan_bagas_'.$dataset.'_'.date('Ymd_His');if($format==='json'){header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'.json"');echo json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);exit;}header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'.csv"');$out=fopen('php://output','w');if($data)fputcsv($out,array_keys($data[0]));foreach($data as $row)fputcsv($out,$row);fclose($out);exit;}
$user=currentUser($pdo);require __DIR__.'/includes/header.php';
?>
